export const supportedLanguages = Object.freeze(['zh-CN', 'en', 'ja', 'es', 'de', 'ko']);
export function translationKeys(language) {
  return Object.keys(messages[resolveLanguage(language)]);
}
export function resolveLanguage(value) {
  const lang = String(value || '').toLowerCase();
  if (lang.startsWith('zh')) return 'zh-CN';
  if (lang.startsWith('ja')) return 'ja';
  if (lang.startsWith('es')) return 'es';
  if (lang.startsWith('de')) return 'de';
  if (lang.startsWith('ko')) return 'ko';
  return 'en';
}
export function translate(language, key, values = {}) {
  const template = messages[resolveLanguage(language)][key] ?? messages.en[key] ?? key;
  return template.replace(/\{(\w+)\}/g, (match, name) => Object.hasOwn(values, name) ? String(values[name]) : match);
}
export function applyTranslations(root, language) {
  root.documentElement.lang = resolveLanguage(language);
  for (const node of root.querySelectorAll('[data-i18n]')) node.textContent = translate(language, node.dataset.i18n);
  for (const node of root.querySelectorAll('[data-i18n-placeholder]')) node.placeholder = translate(language, node.dataset.i18nPlaceholder);
}
export function contentMessages(language) {
  const keys = ['translationFailed', 'translationLabel', 'retry', 'retryTitle', 'rechecking', 'requestFailed', 'translating', 'progressParallel', 'progressStopped', 'progressFailed', 'progressDone', 'progressError', 'noParagraphs', 'noNewParagraphs', 'limitWarning', 'quickTranslate', 'quickTranslateTitle', 'quickClose', 'quickMove', 'quickStarting', 'quickError'];
  return Object.fromEntries(keys.map(key => [key, translate(language, key)]));
}

const endpointErrors = {
  'Enter an API base URL.': ['请填写 API 基础地址。', 'Enter an API base URL.', 'API ベース URL を入力してください。', 'Introduce una URL base de API.'],
  'Invalid API base URL.': ['API 基础地址无效。', 'Invalid API base URL.', 'API ベース URL が無効です。', 'La URL base de API no es válida.'],
  'Only HTTPS endpoints are supported (HTTP is allowed for localhost).': ['仅支持 HTTPS，本机服务可使用 HTTP。', 'Only HTTPS endpoints are supported (HTTP is allowed for localhost).', 'HTTPS のみ対応しています（ローカルでは HTTP 可）。', 'Solo se admite HTTPS (HTTP se permite en localhost).'],
  'Do not include credentials, query strings, or fragments in the API URL.': ['API 地址不得包含凭据、查询参数或片段。', 'Do not include credentials, query strings, or fragments in the API URL.', 'API URL に認証情報、クエリ、フラグメントを含めないでください。', 'No incluyas credenciales, consultas ni fragmentos en la URL de API.'],
  'HTTP is allowed only for local model servers. Use HTTPS for remote APIs.': ['HTTP 仅适用于本机模型服务，远程 API 请使用 HTTPS。', 'HTTP is allowed only for local model servers. Use HTTPS for remote APIs.', 'HTTP はローカルサーバーのみで使用できます。リモート API は HTTPS を使用してください。', 'HTTP solo se permite para servidores locales. Usa HTTPS para API remotas.'],
  'Use localhost or 127.0.0.1 instead of an IPv6 loopback address.': ['请使用 localhost 或 127.0.0.1，不要使用 IPv6 回环地址。', 'Use localhost or 127.0.0.1 instead of an IPv6 loopback address.', 'IPv6 ループバックの代わりに localhost または 127.0.0.1 を使用してください。', 'Usa localhost o 127.0.0.1 en lugar de una dirección IPv6 local.']
};
export function localizeError(language, error) {
  const original = String(error?.message || error);
  const variants = endpointErrors[original];
  const index = supportedLanguages.indexOf(resolveLanguage(language));
  return variants ? variants[index] || variants[1] : original;
}
